#!/usr/bin/env python3
"""Text files (pad scripts) as C strings in one generated header, so a build carries them without a data file: a
menu entry can write one out and play it (kh1-vita's debug start writes its pad script to the data folder and plays
it as config.txt's pad=). Blank lines and lines starting with `#` are left out; each kept line ends in `\\n`.

  vita/tools/embed_pad.py OUT.h NAME=SCRIPT.txt [NAME=SCRIPT.txt ...]          write OUT.h
  vita/tools/embed_pad.py --check OUT.h NAME=SCRIPT.txt [...]                  exit 1 when OUT.h differs

Run --check in the game's tests so an edited script with a stale header fails.
From kh1-vita tools/vita/embed_pad.py @ 75afd241, with the paths and names made arguments. Python 3, stdlib.
"""
import os
import re
import sys


def header(out, pairs):
    srcs = " and ".join(os.path.basename(src) for _, src in pairs)
    lines = ["/* generated by vita/tools/embed_pad.py from %s: do not edit */" % srcs]
    for name, src in pairs:
        lines.append("static const char %s[] =" % name)
        kept = 0
        with open(src, encoding="utf-8") as f:
            for ln in f.read().splitlines():
                if not ln.strip() or ln.startswith("#"):
                    continue
                lines.append('    "%s\\n"' % ln.replace("\\", "\\\\").replace('"', '\\"'))
                kept += 1
        if not kept:
            lines.append('    ""')
        lines[-1] += ";"
    return "\n".join(lines) + "\n"


def main(argv):
    check = "--check" in argv
    args = [a for a in argv if a != "--check"]
    if len(args) < 2:
        print(__doc__, file=sys.stderr)
        return 2
    out, pairs = args[0], []
    for a in args[1:]:
        name, sep, src = a.partition("=")
        if not sep or not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name):
            print("embed_pad: %r is not NAME=SCRIPT.txt" % a, file=sys.stderr)
            return 2
        pairs.append((name, src))
    h = header(out, pairs)
    if check:
        cur = open(out, encoding="utf-8").read() if os.path.exists(out) else ""
        if cur != h:
            print("embed_pad: %s is not its scripts': run vita/tools/embed_pad.py" % out)
            return 1
        print("embed_pad: %s matches its scripts" % out)
        return 0
    with open(out, "w", encoding="utf-8") as f:
        f.write(h)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
